 29	public class Main {
 30	    public static void main(String[] args) {
 31	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 32	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 33	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
