 42	        try {
 43	            roomRepository.createTable();
 44	            reservationRepository.createTable();
 45	            messageRepository.createTable();
 46	
 47	            initializeRooms(roomRepository);
 48	        } catch (SQLException e) {
 49	            System.err.println("Failed to initialize database: " + e.getMessage());
 50	            System.exit(1);
