136	package com.pousadamarealta.service;
137	
138	import com.pousadamarealta.domain.events.ReservationCancelledEvent;
139	import com.pousadamarealta.domain.events.ReservationConfirmedEvent;
140	import com.pousadamarealta.domain.model.*;
141	import com.pousadamarealta.repository.ReservationRepository;
142	import com.pousadamarealta.repository.RoomRepository;
143	import com.pousadamarealta.util.PriceCalculator;
144	
145	import java.math.BigDecimal;
146	import java.sql.SQLException;
147	import java.time.LocalDate;
148	import java.time.temporal.ChronoUnit;
149	import java.util.List;
150	import java.util.Optional;
151	
152	public class ReservationService {
153	    private final ReservationRepository reservationRepository;
154	    private final RoomRepository roomRepository;
155	    private final EventPublisher eventPublisher;
156	
157	    public ReservationService(ReservationRepository reservationRepository,
158	                            RoomRepository roomRepository,
159	                            EventPublisher eventPublisher) {
160	        this.reservationRepository = reservationRepository;
161	        this.roomRepository = roomRepository;
162	        this.eventPublisher = eventPublisher;
163	    }
164	
165	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
166	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
167	                                        int guests, RatePlan ratePlan) {
168	        Room room;
169	        try {
170	            room = roomRepository.findByNumber(roomNumber)
171	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
172	        } catch (SQLException e) {
173	            throw new RuntimeException("Failed to retrieve room", e);
174	        }
175	
176	        if (guests < 1) {
177	            throw new InvalidRequestException("At least one guest is required");
178	        }
179	
180	        if (guests > room.getCapacity()) {
181	            throw new CapacityExceededException("Room capacity exceeded");
182	        }
183	
184	        if (!checkOut.isAfter(checkIn)) {
185	            throw new InvalidRequestException("Check-out must be after check-in");
186	        }
187	
188	        List<Reservation> conflicts;
189	        try {
190	            conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
191	        } catch (SQLException e) {
192	            throw new RuntimeException("Failed to check room availability", e);
193	        }
194	
195	        if (!conflicts.isEmpty()) {
196	            throw new RoomUnavailableException("Room is not available for the selected dates");
197	        }
198	
199	        Reservation reservation = new Reservation();
200	        reservation.setRoomNumber(roomNumber);
201	        reservation.setGuestName(guestName);
202	        reservation.setGuestEmail(guestEmail);
203	        reservation.setGuestCpf(guestCpf);
204	        reservation.setCheckIn(checkIn);
205	        reservation.setCheckOut(checkOut);
206	        reservation.setGuests(guests);
207	        reservation.setRatePlan(ratePlan);
208	
209	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
210	        reservation.setNights(nights);
211	
212	        BigDecimal subtotal = BigDecimal.ZERO;
213	        LocalDate currentNight = checkIn;
214	        for (int i = 0; i < nights; i++) {
215	            BigDecimal nightPrice = PriceCalculator.calculateNightPrice(room.getNightlyRate(), currentNight);
216	            subtotal = subtotal.add(nightPrice);
217	            currentNight = currentNight.plusDays(1);
218	        }
219	        subtotal = PriceCalculator.roundMoney(subtotal);
220	        reservation.setSubtotal(subtotal);
221	
222	        boolean isNonRefundable = ratePlan == RatePlan.NON_REFUNDABLE;
223	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, isNonRefundable);
224	        reservation.setDiscount(discount);
225	
226	        BigDecimal total = PriceCalculator.roundMoney(subtotal.subtract(discount));
227	        reservation.setTotal(total);
228	
229	        try {
230	            return reservationRepository.save(reservation);
231	        } catch (SQLException e) {
232	            throw new RuntimeException("Failed to create reservation", e);
233	        }
234	    }
235	
236	    public Reservation getReservation(Long id) {
237	        try {
238	            return reservationRepository.findById(id)
239	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
240	        } catch (SQLException e) {
241	            throw new RuntimeException("Failed to retrieve reservation", e);
242	        }
243	    }
244	
245	    public Reservation confirmReservation(Long id) {
246	        Reservation reservation = getReservation(id);
247	
248	        if (reservation.getStatus() != ReservationStatus.PENDING) {
249	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
250	        }
251	
252	        reservation.setStatus(ReservationStatus.CONFIRMED);
253	        reservation.setAmountPaid(reservation.getTotal());
254	
255	        try {
256	            reservation = reservationRepository.save(reservation);
257	            eventPublisher.publish(new ReservationConfirmedEvent(reservation));
258	            return reservation;
259	        } catch (SQLException e) {
260	            throw new RuntimeException("Failed to confirm reservation", e);
261	        }
262	    }
263	
264	    public Reservation cancelReservation(Long id) {
265	        Reservation reservation = getReservation(id);
266	
267	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
268	            reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
269	            throw new OperationNotAllowedException("Cannot cancel reservation after check-in");
270	        }
271	
272	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
273	            throw new OperationNotAllowedException("Reservation is already cancelled");
274	        }
275	
276	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
277	
278	        BigDecimal refund = BigDecimal.ZERO;
279	        if (wasConfirmed && reservation.getRatePlan() == RatePlan.STANDARD) {
280	            refund = reservation.getAmountPaid();
281	        }
282	
283	        reservation.setStatus(ReservationStatus.CANCELLED);
284	        reservation.setRefund(refund);
285	
286	        try {
287	            reservation = reservationRepository.save(reservation);
288	            eventPublisher.publish(new ReservationCancelledEvent(reservation, wasConfirmed));
289	            return reservation;
290	        } catch (SQLException e) {
291	            throw new RuntimeException("Failed to cancel reservation", e);
292	        }
293	    }
294	
295	    public Reservation checkIn(Long id) {
296	        Reservation reservation = getReservation(id);
297	
298	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
299	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
300	        }
301	
302	        reservation.setStatus(ReservationStatus.CHECKED_IN);
303	
304	        try {
305	            return reservationRepository.save(reservation);
306	        } catch (SQLException e) {
307	            throw new RuntimeException("Failed to check in", e);
308	        }
309	    }
310	
311	    public Reservation checkOut(Long id) {
312	        Reservation reservation = getReservation(id);
313	
314	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
315	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
316	        }
317	
318	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
319	
320	        try {
321	            return reservationRepository.save(reservation);
322	        } catch (SQLException e) {
323	            throw new RuntimeException("Failed to check out", e);
324	        }
325	    }
326	
327	    public List<Reservation> getReservationsByDate(LocalDate date) {
328	        try {
329	            return reservationRepository.findByDate(date);
330	        } catch (SQLException e) {
331	            throw new RuntimeException("Failed to retrieve reservations", e);
332	        }
333	    }
334	
335	    public List<Reservation> getReservationsByMonth(int year, int month) {
336	        try {
337	            return reservationRepository.findByMonth(year, month);
338	        } catch (SQLException e) {
339	            throw new RuntimeException("Failed to retrieve reservations", e);
340	        }
341	    }
342	
343	    public static class RoomNotFoundException extends RuntimeException {
344	        public RoomNotFoundException(String message) {
345	            super(message);
346	        }
347	    }
348	
349	    public static class ReservationNotFoundException extends RuntimeException {
350	        public ReservationNotFoundException(String message) {
351	            super(message);
352	        }
353	    }
354	
355	    public static class InvalidRequestException extends RuntimeException {
356	        public InvalidRequestException(String message) {
357	            super(message);
358	        }
359	    }
360	
361	    public static class RoomUnavailableException extends RuntimeException {
362	        public RoomUnavailableException(String message) {
363	            super(message);
364	        }
365	    }
366	
367	    public static class CapacityExceededException extends RuntimeException {
368	        public CapacityExceededException(String message) {
369	            super(message);
370	        }
371	    }
372	
373	    public static class OperationNotAllowedException extends RuntimeException {
374	        public OperationNotAllowedException(String message) {
375	            super(message);
376	        }
377	    }
378	}
379	package com.pousadamarealta.service;
380	
381	import com.pousadamarealta.domain.events.ReservationEvent;
382	import com.pousadamarealta.domain.events.EventListener;
383	
384	import java.util.ArrayList;
385	import java.util.HashMap;
386	import java.util.List;
387	import java.util.Map;
388	
389	public class EventPublisher {
390	    private final Map<Class<? extends ReservationEvent>, List<EventListener<? extends ReservationEvent>>> listeners = new HashMap<>();
391	
392	    public <T extends ReservationEvent> void register(Class<T> eventType, EventListener<T> listener) {
393	        listeners.computeIfAbsent(eventType, k -> new ArrayList<>()).add(listener);
394	    }
395	
396	    @SuppressWarnings("unchecked")
397	    public <T extends ReservationEvent> void publish(T event) {
398	        List<EventListener<? extends ReservationEvent>> eventListeners = listeners.get(event.getClass());
399	        if (eventListeners != null) {
400	            for (EventListener<? extends ReservationEvent> listener : eventListeners) {
401	                ((EventListener<T>) listener).handle(event);
402	            }
403	        }
404	    }
405	}

