139	    @Override
140	    public void handle(ReservationConfirmedEvent event) {
141	        Reservation r = event.getReservation();
142	
143	        String subject = "Reserva confirmada - Pousada Maré Alta";
144	        String body = buildConfirmationEmail(r);
