149	    private String buildConfirmationEmail(Reservation r) {
150	        StringBuilder sb = new StringBuilder();
151	        sb.append("Olá, ").append(r.getGuestName()).append("!\n\n");
152	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
153	        sb.append(buildReceipt(r));
154	        sb.append("\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
155	        sb.append("Até breve!");
156	        return sb.toString();
157	    }
158	
159	    private String buildReceipt(Reservation r) {
160	        StringBuilder sb = new StringBuilder();
161	        sb.append("Comprovante de reserva nº ").append(r.getId()).append("\n");
162	        sb.append("Hóspede: ").append(r.getGuestName())
163	          .append(" (CPF ").append(Formatter.formatCpf(r.getGuestCpf())).append(")\n");
164	
165	        String roomType = getRoomTypeName(r.getRoomNumber());
166	        sb.append("Quarto: ").append(r.getRoomNumber())
167	          .append(" (").append(roomType).append(")\n");
168	
169	        sb.append("Entrada: ").append(Formatter.formatDate(r.getCheckIn()))
170	          .append(" | Saída: ").append(Formatter.formatDate(r.getCheckOut()))
171	          .append(" | ").append(r.getNights()).append(r.getNights() == 1 ? " diária" : " diárias").append("\n");
172	
173	        sb.append("Diárias: ").append(Formatter.formatMoney(r.getSubtotal())).append("\n");
174	
175	        if (r.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
176	            sb.append("Desconto: ").append(Formatter.formatMoney(r.getDiscount())).append("\n");
177	        }
178	
179	        sb.append("Total: ").append(Formatter.formatMoney(r.getTotal()));
180	
181	        return sb.toString();
182	    }
183	
184	    private String getRoomTypeName(String roomNumber) {
185	        return switch (roomNumber) {
186	            case "101", "102" -> "STANDARD";
187	            case "201", "202" -> "DELUXE";
188	            case "301" -> "SUITE";
189	            default -> "";
190	        };
191	    }
192	}
