 37	
 38	public class ReportController {
 39	    private final ReservationService reservationService;
 40	    private final RoomService roomService;
 41	    private final int totalRooms;
 42	
 43	    public ReportController(ReservationService reservationService, RoomService roomService) {
 44	        this.reservationService = reservationService;
 45	        this.roomService = roomService;
 46	        this.totalRooms = roomService.getAllRooms().size();
 47	    }
 48	
 49	    public void getOccupancyReport(Context ctx) {
 50	        String dateStr = ctx.queryParam("date");
 51	
 52	        if (dateStr == null) {
 53	            ctx.status(HttpStatus.BAD_REQUEST)
 54	               .json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
 55	            return;
 56	        }
 57	
 58	        try {
 59	            LocalDate date = LocalDate.parse(dateStr);
 60	            List<Reservation> reservations = reservationService.getReservationsByDate(date);
 61	
 62	            StringBuilder csv = new StringBuilder();
 63	            csv.append("room,type,reservation,check_in,check_out\n");
 64	
 65	            for (Reservation r : reservations) {
 66	                csv.append(r.getRoomNumber()).append(",");
 67	                csv.append(getRoomTypeName(r.getRoomNumber())).append(",");
 68	                csv.append(r.getId()).append(",");
 69	                csv.append(r.getCheckIn()).append(",");
 70	                csv.append(r.getCheckOut()).append("\n");
 71	            }
 72	
 73	            csv.append("total,").append(reservations.size()).append("/").append(totalRooms);
 74	
 75	            ctx.contentType("text/csv; charset=utf-8")
 76	               .result(csv.toString());
 77	
 78	        } catch (DateTimeParseException e) {
 79	            ctx.status(HttpStatus.BAD_REQUEST)
 80	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
 81	        }
 82	    }
 83	
 84	    public void getRevenueReport(Context ctx) {
 85	        String monthStr = ctx.queryParam("month");
 86	
 87	        if (monthStr == null) {
 88	            ctx.status(HttpStatus.BAD_REQUEST)
 89	               .json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
 90	            return;
 91	        }
 92	
 93	        try {
 94	            String[] parts = monthStr.split("-");
 95	            if (parts.length != 2) {
 96	                throw new DateTimeParseException("Invalid format", monthStr, 0);
 97	            }
 98	
 99	            int year = Integer.parseInt(parts[0]);
100	            int month = Integer.parseInt(parts[1]);
101	
102	            if (month < 1 || month > 12) {
103	                throw new DateTimeParseException("Invalid month", monthStr, 0);
104	            }
105	
106	            List<Reservation> reservations = reservationService.getReservationsByMonth(year, month);
107	
108	            StringBuilder csv = new StringBuilder();
109	            csv.append("reservation,room,check_in,check_out,status,amount\n");
110	
111	            BigDecimal totalAmount = BigDecimal.ZERO;
112	
113	            for (Reservation r : reservations) {
114	                BigDecimal netAmount = r.getAmountPaid();
115	                if (r.getRefund() != null) {
116	                    netAmount = netAmount.subtract(r.getRefund());
117	                }
118	
119	                csv.append(r.getId()).append(",");
120	                csv.append(r.getRoomNumber()).append(",");
121	                csv.append(r.getCheckIn()).append(",");
122	                csv.append(r.getCheckOut()).append(",");
123	                csv.append(r.getStatus().name()).append(",");
124	                csv.append(String.format("%.2f", netAmount.doubleValue())).append("\n");
125	
126	                totalAmount = totalAmount.add(netAmount);
127	            }
128	
129	            csv.append("total,").append(String.format("%.2f", totalAmount.doubleValue()));
130	
131	            ctx.contentType("text/csv; charset=utf-8")
132	               .result(csv.toString());
133	
134	        } catch (DateTimeParseException | NumberFormatException e) {
135	            ctx.status(HttpStatus.BAD_REQUEST)
136	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
137	        }
138	    }
139	
140	    private String getRoomTypeName(String roomNumber) {
141	        return switch (roomNumber) {
142	            case "101", "102" -> "STANDARD";
143	            case "201", "202" -> "DELUXE";
144	            case "301" -> "SUITE";
145	            default -> "";
146	        };
147	    }
148	}
