167	
168	    public ReservationController(ReservationService reservationService) {
169	        this.reservationService = reservationService;
170	    }
171	
172	    public void createReservation(Context ctx) {
173	        try {
174	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
175	
176	            if (req.getRoomNumber() == null || req.getGuestName() == null ||
177	                req.getGuestEmail() == null || req.getGuestCpf() == null ||
178	                req.getCheckIn() == null || req.getCheckOut() == null ||
179	                req.getGuests() == null || req.getRatePlan() == null) {
180	                ctx.status(HttpStatus.BAD_REQUEST)
181	                   .json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
182	                return;
183	            }
184	
185	            LocalDate checkIn;
186	            LocalDate checkOut;
187	            try {
188	                checkIn = LocalDate.parse(req.getCheckIn());
189	                checkOut = LocalDate.parse(req.getCheckOut());
190	            } catch (DateTimeParseException e) {
191	                ctx.status(HttpStatus.BAD_REQUEST)
192	                   .json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
193	                return;
194	            }
195	
196	            RatePlan ratePlan;
197	            try {
198	                ratePlan = RatePlan.valueOf(req.getRatePlan());
199	            } catch (IllegalArgumentException e) {
200	                ctx.status(HttpStatus.BAD_REQUEST)
201	                   .json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
202	                return;
203	            }
204	
205	            Reservation reservation = reservationService.createReservation(
206	                req.getRoomNumber(),
207	                req.getGuestName(),
208	                req.getGuestEmail(),
209	                req.getGuestCpf(),
210	                checkIn,
211	                checkOut,
212	                req.getGuests(),
213	                ratePlan
214	            );
215	
216	            ctx.status(HttpStatus.CREATED).json(DomainMapper.toDTO(reservation));
217	
218	        } catch (ReservationService.RoomNotFoundException e) {
219	            ctx.status(HttpStatus.NOT_FOUND)
220	               .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
221	        } catch (ReservationService.InvalidRequestException e) {
222	            ctx.status(HttpStatus.BAD_REQUEST)
223	               .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
224	        } catch (ReservationService.RoomUnavailableException e) {
225	            ctx.status(HttpStatus.CONFLICT)
226	               .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
227	        } catch (ReservationService.CapacityExceededException e) {
228	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
229	               .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
230	        } catch (Exception e) {
231	            ctx.status(HttpStatus.BAD_REQUEST)
232	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
233	        }
234	    }
235	
236	    public void getReservation(Context ctx) {
237	        try {
238	            Long id = Long.parseLong(ctx.pathParam("id"));
239	            Reservation reservation = reservationService.getReservation(id);
240	            ctx.json(DomainMapper.toDTO(reservation));
241	        } catch (ReservationService.ReservationNotFoundException e) {
242	            ctx.status(HttpStatus.NOT_FOUND)
243	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
244	        } catch (NumberFormatException e) {
245	            ctx.status(HttpStatus.BAD_REQUEST)
246	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
247	        }
248	    }
249	
250	    public void confirmReservation(Context ctx) {
251	        try {
252	            Long id = Long.parseLong(ctx.pathParam("id"));
253	            Reservation reservation = reservationService.confirmReservation(id);
254	            ctx.json(DomainMapper.toDTO(reservation));
255	        } catch (ReservationService.ReservationNotFoundException e) {
256	            ctx.status(HttpStatus.NOT_FOUND)
257	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
258	        } catch (ReservationService.OperationNotAllowedException e) {
259	            ctx.status(HttpStatus.CONFLICT)
260	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
261	        } catch (NumberFormatException e) {
262	            ctx.status(HttpStatus.BAD_REQUEST)
263	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
264	        }
265	    }
266	
267	    public void cancelReservation(Context ctx) {
268	        try {
269	            Long id = Long.parseLong(ctx.pathParam("id"));
270	            Reservation reservation = reservationService.cancelReservation(id);
271	            ctx.json(DomainMapper.toDTO(reservation));
272	        } catch (ReservationService.ReservationNotFoundException e) {
273	            ctx.status(HttpStatus.NOT_FOUND)
274	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
275	        } catch (ReservationService.OperationNotAllowedException e) {
276	            ctx.status(HttpStatus.CONFLICT)
277	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
278	        } catch (NumberFormatException e) {
279	            ctx.status(HttpStatus.BAD_REQUEST)
280	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
281	        }
282	    }
283	
284	    public void checkIn(Context ctx) {
285	        try {
286	            Long id = Long.parseLong(ctx.pathParam("id"));
287	            Reservation reservation = reservationService.checkIn(id);
288	            ctx.json(DomainMapper.toDTO(reservation));
289	        } catch (ReservationService.ReservationNotFoundException e) {
290	            ctx.status(HttpStatus.NOT_FOUND)
291	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
292	        } catch (ReservationService.OperationNotAllowedException e) {
293	            ctx.status(HttpStatus.CONFLICT)
294	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
295	        } catch (NumberFormatException e) {
296	            ctx.status(HttpStatus.BAD_REQUEST)
297	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
298	        }
