301	    public void checkOut(Context ctx) {
302	        try {
303	            Long id = Long.parseLong(ctx.pathParam("id"));
304	            Reservation reservation = reservationService.checkOut(id);
305	            ctx.json(DomainMapper.toDocumentDTO(reservation));
