310	            ctx.status(HttpStatus.CONFLICT)
311	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
312	        } catch (NumberFormatException e) {
313	            ctx.status(HttpStatus.BAD_REQUEST)
314	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
