 10	import java.sql.SQLException;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	
 14	public class MessageRepository {
 15	    private final DataSource dataSource;
 16	
 17	    public MessageRepository(DataSource dataSource) {
 18	        this.dataSource = dataSource;
 19	    }
 20	
 21	    public void createTable() throws SQLException {
 22	        String sql = """
 23	            CREATE TABLE IF NOT EXISTS messages (
 24	                id BIGSERIAL PRIMARY KEY,
 25	                channel VARCHAR(20) NOT NULL,
 26	                recipient VARCHAR(255) NOT NULL,
 27	                subject VARCHAR(500) NOT NULL,
 28	                body TEXT NOT NULL
 29	            )
 30	        """;
 31	
 32	        try (Connection conn = dataSource.getConnection();
 33	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 34	            stmt.execute();
 35	        }
 36	    }
 37	
 38	    public Message save(Message message) throws SQLException {
 39	        String sql = """
 40	            INSERT INTO messages (channel, recipient, subject, body)
 41	            VALUES (?, ?, ?, ?)
 42	            RETURNING id
 43	        """;
 44	
 45	        try (Connection conn = dataSource.getConnection();
 46	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 47	            stmt.setString(1, message.getChannel().name());
 48	            stmt.setString(2, message.getTo());
 49	            stmt.setString(3, message.getSubject());
 50	            stmt.setString(4, message.getBody());
 51	
 52	            try (ResultSet rs = stmt.executeQuery()) {
 53	                if (rs.next()) {
 54	                    message.setId(rs.getLong("id"));
 55	                }
 56	            }
 57	        }
 58	
 59	        return message;
 60	    }
 61	
 62	    public List<Message> findAll() throws SQLException {
 63	        String sql = "SELECT * FROM messages ORDER BY id";
 64	        List<Message> messages = new ArrayList<>();
 65	
 66	        try (Connection conn = dataSource.getConnection();
 67	             PreparedStatement stmt = conn.prepareStatement(sql);
 68	             ResultSet rs = stmt.executeQuery()) {
 69	            while (rs.next()) {
 70	                Message m = new Message();
 71	                m.setId(rs.getLong("id"));
 72	                m.setChannel(MessageChannel.valueOf(rs.getString("channel")));
 73	                m.setTo(rs.getString("recipient"));
 74	                m.setSubject(rs.getString("subject"));
 75	                m.setBody(rs.getString("body"));
 76	                messages.add(m);
 77	            }
 78	        }
 79	
 80	        return messages;
 81	    }
 82	}
