445	import java.math.BigDecimal;
446	import java.math.RoundingMode;
447	import java.time.LocalDate;
448	
449	public class PriceCalculator {
450	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
451	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
452	
453	    public static BigDecimal roundMoney(BigDecimal amount) {
454	        return amount.setScale(2, RoundingMode.HALF_EVEN);
455	    }
456	
457	    public static boolean isHighSeason(LocalDate date) {
458	        int month = date.getMonthValue();
459	        int day = date.getDayOfMonth();
460	
461	        if (month == 7) {
462	            return true;
463	        }
464	
465	        if (month == 12 && day >= 15) {
466	            return true;
467	        }
468	
469	        if (month == 1 || month == 2) {
470	            return true;
471	        }
472	
473	        return false;
474	    }
475	
476	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
477	        BigDecimal price = baseRate;
478	        if (isHighSeason(night)) {
479	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
480	        }
481	        return roundMoney(price);
482	    }
483	
484	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
485	        if (isNonRefundable) {
486	            return roundMoney(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
487	        }
488	        return BigDecimal.ZERO;
489	    }
490	}

